        "text_kwargs": {},
        "images_kwargs": {},
        "audio_kwargs": {},
        "videos_kwargs": {},
    }

    default_kwargs = {
        "text_kwargs": {},
        "images_kwargs": {},
        "audio_kwargs": {},
        "videos_kwargs": {},
    }

    map_preprocessor_kwargs = {
        "text_kwargs": "tokenizer",
